"""Independent evaluations generated by the pinned current legacy source."""

import json
from pathlib import Path

import pytest

from claasp.primitives._catalogue_exports import load_export

FIXTURE = json.loads(Path("tests/fixtures/legacy_parity/constructor_options.json").read_text())


@pytest.mark.parametrize("case", FIXTURE["cases"])
def test_legacy_nondefault_options(case):
    primitive = load_export(case["class"])(**case["options"])
    assert primitive.evaluate(*case["inputs"]) == case["expected"]
